#!/bin/sh
# Generated by android-repo-docs bootstrap; regenerate after changing tooling_ref.
set -eu
root=$(CDPATH= cd -- "$(dirname -- "$0")" && pwd)
pin='8e7d731e798ff9defcd71b2b146958e0ab3e146a'
actual=$(tr -d '\r' < "$root/.project/docs/config.yaml" | sed -n -E "s/^(tooling_ref|'tooling_ref'|\"tooling_ref\")[[:blank:]]*:[[:blank:]]*([a-z0-9.]+|'[a-z0-9.]+'|\"[a-z0-9.]+\")([[:blank:]]+#.*|[[:blank:]]*)$/\2/p" | tr -d "\"'")
[ "$actual" = "$pin" ] || { echo 'tooling_ref changed; regenerate bootstrap with the pinned CLI' >&2; exit 1; }
cache="$root/.project/docs/cache"
for path in "$root/.project" "$root/.project/docs" "$cache" "$cache/$pin"; do
  [ ! -L "$path" ] || { echo "Refusing symlink: $path" >&2; exit 1; }
done
mkdir -p "$cache"
exe="$cache/$pin/bin/android-repo-docs"
if [ -L "$cache/$pin/bin" ] || [ -L "$exe" ]; then echo 'Refusing symlink in binary cache' >&2; exit 1; fi
if [ ! -x "$exe" ]; then
  stage=$(mktemp -d "$cache/.install.XXXXXXXX")
  trap 'rm -rf "$stage"' EXIT HUP INT TERM
  case "$pin" in
    v*)
      if [ "${ANDROID_REPO_DOCS_SOURCE:-0}" = 1 ]; then
        CARGO_TARGET_DIR="$stage/target" cargo install --locked --root "$stage" --git https://github.com/lambdawalker/gradle.android-repo-setup.git --tag "$pin" android-repo-docs
      else
      case "$(uname -s):$(uname -m)" in
        Linux:x86_64) target=x86_64-unknown-linux-gnu ;;
        Darwin:arm64) target=aarch64-apple-darwin ;;
        *) echo 'No release binary for this platform. Install Rust and use a full commit SHA tooling_ref for a cached source build.' >&2; exit 1 ;;
      esac
      archive="android-repo-docs-$target.tar.gz"
      url="https://github.com/lambdawalker/gradle.android-repo-setup/releases/download/$pin/$archive"
      curl --fail --silent --show-error --location "$url" -o "$stage/$archive"
      curl --fail --silent --show-error --location "$url.sha256" -o "$stage/checksum"
      hash=$(awk 'NR==1 {print $1}' "$stage/checksum")
      [ "${#hash}" = 64 ] && ! printf '%s' "$hash" | grep -q '[^0-9a-fA-F]' || { echo 'Invalid SHA256 checksum' >&2; exit 1; }
      if command -v sha256sum >/dev/null 2>&1; then calculated=$(sha256sum "$stage/$archive" | awk '{print $1}'); else calculated=$(shasum -a 256 "$stage/$archive" | awk '{print $1}'); fi
      [ "$calculated" = "$hash" ] || { echo 'SHA256 checksum mismatch' >&2; exit 1; }
      mkdir "$stage/bin"
      tar -xzf "$stage/$archive" -C "$stage/bin" android-repo-docs
      chmod +x "$stage/bin/android-repo-docs"
      fi
      ;;
    *) CARGO_TARGET_DIR="$stage/target" cargo install --locked --root "$stage" --git https://github.com/lambdawalker/gradle.android-repo-setup.git --rev "$pin" android-repo-docs ;;
  esac
  version=$("$stage/bin/android-repo-docs" --version)
  case "$pin" in v*) [ "$version" = "android-repo-docs ${pin#v}" ] || { echo 'Downloaded CLI version mismatch' >&2; exit 1; };; *) case "$version" in 'android-repo-docs '*) ;; *) echo 'Invalid CLI version' >&2; exit 1;; esac;; esac
  rm -rf "$stage/target"
  [ ! -e "$cache/$pin" ] || { echo 'Invalid existing cache; remove it and retry' >&2; exit 1; }
  mv "$stage" "$cache/$pin"
  trap - EXIT HUP INT TERM
fi
version=$("$exe" --version)
case "$pin" in v*) [ "$version" = "android-repo-docs ${pin#v}" ] || { echo 'Cached CLI version mismatch' >&2; exit 1; };; esac
PATH="$cache/$pin/bin:$PATH"
export PATH
exec "$exe" --project "$root" "$@"
